#!/usr/bin/env node
// Regenerate cat_for_eng decompositions nulled by the K42 bracket-tag repair (#20·K).
// Why direct, not POST /api/admin/decomposition-backfill: that endpoint needs an admin session
// and decomposes with plain decomposeText (no salient anchor); this uses decomposeAnchored, as
// refresh-stale-phrase-decompositions.cjs does. Writes decomposition + version stamp ONLY.
// display_tiling is not generated by any server code (null on all cat rows) — left alone.
// Usage: node <this> [--apply]   (dry run default)
require('dotenv').config({ path: require('path').join(__dirname, '..', '..', '.env.psql'), quiet: true });
require('dotenv').config({ path: require('path').join(__dirname, '..', '..', '.env'), quiet: true });
const fs = require('fs'), os = require('os'), path = require('path');
const { Client } = require('pg');
const { decomposeAnchored } = require('../../services/phrase-decomposer.cjs');
const APPLY = process.argv.includes('--apply');
const COURSE = 'cat_for_eng';
const BEFORE = path.join(os.homedir(), 'ssi-evidence/ssi-dashboard-v7/cat-bracket-cache-repair-2026-10-06-before.json');
const id2 = (s, i) => `S${String(s).padStart(4, '0')}L${String(i).padStart(2, '0')}`;
(async () => {
  const ids = new Set(JSON.parse(fs.readFileSync(BEFORE, 'utf8')).map((r) => r.id));
  const c = new Client({ connectionString: process.env.DATABASE_URL }); await c.connect();
  const { rows: legos } = await c.query('select seed_number, lego_index, target_text, known_text from course_legos where course_code=$1', [COURSE]);
  const vocab = legos.map((l) => ({ lego_id: id2(l.seed_number, l.lego_index), target_text: l.target_text, known_text: l.known_text, seed_number: l.seed_number }));
  const byId = new Map(vocab.map((l) => [l.lego_id, l]));
  const { rows: [{ version }] } = await c.query('select version from courses where course_code=$1', [COURSE]);
  const { rows } = await c.query('select id, seed_number, lego_index, target_text from course_practice_phrases where course_code=$1 and decomposition is null and id = any($2)', [COURSE, [...ids]]);
  const log = { applied: [], skipped: [] };
  let eventId = null;
  if (APPLY) {
    const { createClient } = require('@supabase/supabase-js');
    const sb = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);
    const { serviceIdentity } = require('../../services/shared/editor-identity.cjs');
    const { recordContentEdit } = require('../../services/shared/content-edit-log.cjs');
    eventId = await recordContentEdit(sb, { identity: serviceIdentity('cat-regen-decompositions', { role: 'content-sweep' }), courseCode: COURSE, surface: 'tools/course-optimization/cat-regen-decompositions-2026-10-06.cjs', operation: 'decomposition_regen', scope: { course_code: COURSE, rows: rows.length }, detail: { job: '#21·K', after: '#20·K bracket-tag cache null' } });
  }
  for (const p of rows) {
    const parent = byId.get(id2(p.seed_number, p.lego_index)) || null;
    let r; try { r = decomposeAnchored(p.target_text, vocab.filter((l) => l.seed_number <= p.seed_number), parent, COURSE); } catch (e) { log.skipped.push({ id: p.id, why: e.message }); continue; }
    if (r.kind === 'error') { log.skipped.push({ id: p.id, why: 'parent_unlocatable' }); continue; }
    if (APPLY) await c.query('update course_practice_phrases set decomposition=$1, decomposition_course_version=$2, last_edit_event_id=$3 where id=$4 and decomposition is null', [JSON.stringify(r.blocks), version, eventId, p.id]);
    log.applied.push({ id: p.id, target: p.target_text, blocks: r.blocks });
  }
  const out = path.join(os.homedir(), `ssi-evidence/ssi-dashboard-v7/cat-regen-decompositions-2026-10-06-${APPLY ? 'applied' : 'dryrun'}.json`);
  fs.writeFileSync(out, JSON.stringify(log, null, 1));
  console.log(`candidates ${rows.length}, ${APPLY ? 'applied' : 'would apply'} ${log.applied.length}, skipped ${log.skipped.length}\n${out}`);
  await c.end();
})();
